shader.fragmentShader:
#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_image;
uniform float u_time;
uniform vec2 u_resolution;
uniform float u_intensity;
uniform float u_speed;
void main() {
  vec2 uv = v_uv;
  float shift = sin(u_time * 25.0 * u_speed) * 0.015 * u_intensity;
  float r = texture(u_image, uv + vec2(shift, 0.0)).r;
  float g = texture(u_image, uv).g;
  float b = texture(u_image, uv - vec2(shift, 0.0)).b;
  fragColor = vec4(r, g, b, texture(u_image, uv).a);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_image;
uniform float u_intensity;
void main() {
  vec2 uv = v_uv;
  vec4 color = vec4(0.0);
  float total = 0.0;
  vec2 dir = vec2(0.008 * u_intensity, 0.0);
  for (float i = -4.0; i <= 4.0; i += 1.0) {
    float weight = 1.0 - abs(i) / 5.0;
    color += texture(u_image, uv + dir * i) * weight;
    total += weight;
  }
  fragColor = color / total;
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_image;
uniform float u_time;
uniform float u_intensity;
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}
void main() {
  vec4 src = texture(u_image, v_uv);
  float n = (hash(v_uv * 600.0 + fract(u_time * 12.0)) - 0.5) * 0.18 * u_intensity;
  fragColor = vec4(clamp(src.rgb + n, 0.0, 1.0), src.a);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_image;
uniform float u_intensity;
void main() {
  vec2 center = vec2(0.5, 0.5);
  vec2 toCenter = center - v_uv;
  vec4 col = vec4(0.0);
  for (int i = 0; i < 8; i++) {
    float scale = 1.0 - 0.015 * float(i) * u_intensity;
    col += texture(u_image, center - toCenter * scale);
  }
  fragColor = col / 8.0;
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_image;
uniform float u_time;
uniform float u_intensity;
void main() {
  vec2 uv = v_uv;
  float scanline = sin(uv.y * 800.0) * 0.04 * u_intensity;
  float glitch = step(0.98, fract(sin(uv.y * 20.0 + u_time * 5.0) * 43758.54)) * 0.02 * u_intensity;
  vec4 col = texture(u_image, vec2(uv.x + glitch, uv.y));
  fragColor = vec4(col.rgb - scanline, col.a);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_image;
uniform float u_time;
uniform float u_intensity;
void main() {
  vec4 c = texture(u_image, v_uv);
  float pulse = (sin(u_time * 4.0) * 0.5 + 0.5) * 0.3 * u_intensity;
  fragColor = vec4(c.rgb + c.rgb * pulse, c.a);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_image;
uniform float u_intensity;
void main() {
  vec2 dist = v_uv - 0.5;
  float r = texture(u_image, 0.5 + dist * (1.0 + 0.02 * u_intensity)).r;
  float g = texture(u_image, v_uv).g;
  float b = texture(u_image, 0.5 + dist * (1.0 - 0.02 * u_intensity)).b;
  fragColor = vec4(r, g, b, texture(u_image, v_uv).a);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_image;
uniform float u_time;
uniform float u_intensity;
void main() {
  vec4 c = texture(u_image, v_uv);
  float leak = max(0.0, 1.0 - distance(v_uv, vec2(0.1, 0.1)) * 1.5) * (0.8 + 0.2 * sin(u_time * 2.0)) * u_intensity;
  vec3 warm = vec3(1.0, 0.55, 0.15);
  fragColor = vec4(c.rgb + warm * leak * 0.45, c.a);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_texA;
uniform sampler2D u_texB;
uniform float u_progress;
void main() {
  vec2 center = vec2(0.5, 0.5);
  float p = u_progress;
  vec2 uvA = center + (v_uv - center) * (1.0 + p * 1.5);
  vec2 uvB = center + (v_uv - center) * (0.5 + p * 0.5);
  vec4 colA = texture(u_texA, uvA);
  vec4 colB = texture(u_texB, uvB);
  fragColor = mix(colA, colB, p);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_texA;
uniform sampler2D u_texB;
uniform float u_progress;
void main() {
  float p = u_progress;
  float slice = fract(sin(floor(v_uv.y * 30.0) * 123.45) * 43758.54);
  float threshold = p + (slice - 0.5) * 0.2;
  fragColor = v_uv.x < threshold ? texture(u_texB, v_uv) : texture(u_texA, v_uv);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_texA;
uniform sampler2D u_texB;
uniform float u_progress;
void main() {
  float p = u_progress;
  vec2 uvA = v_uv - vec2(p, 0.0);
  vec2 uvB = v_uv + vec2(1.0 - p, 0.0);
  fragColor = p < 0.5 ? texture(u_texA, uvA) : texture(u_texB, uvB);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_texA;
uniform sampler2D u_texB;
uniform float u_progress;
void main() {
  float p = u_progress;
  vec4 col = p < 0.5 ? texture(u_texA, v_uv) * (1.0 - p * 2.0) : texture(u_texB, v_uv) * ((p - 0.5) * 2.0);
  fragColor = col;
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_texA;
uniform sampler2D u_texB;
uniform float u_progress;
void main() {
  fragColor = mix(texture(u_texA, v_uv), texture(u_texB, v_uv), u_progress);
}

#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_texA;
uniform sampler2D u_texB;
uniform float u_progress;
void main() {
  float angle = u_progress * 3.14159;
  vec2 pt = v_uv - 0.5;
  mat2 rot = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
  vec2 rotUv = 0.5 + rot * pt;
  fragColor = u_progress < 0.5 ? texture(u_texA, rotUv) : texture(u_texB, rotUv);
}
